using CashFlow.Launch.Domain.Entities;using CashFlow.Launch.Domain.Enums;using CashFlow.Launch.Domain.Interfaces;using CashFlow.Launch.Domain.Interfaces.Services;using CashFlow.Launch.Domain.Models;
namespace CashFlow.Launch.Domain.Services;
public class CreditCardService:ICreditCardService{private readonly ICreditCardRepository _cardRepository;private readonly ICreditCardPurchaseRepository _purchaseRepository;private readonly ICreditCardInstallmentRepository _installmentRepository;private readonly ICategoryRepository _categoryRepository;public CreditCardService(ICreditCardRepository c,ICreditCardPurchaseRepository p,ICreditCardInstallmentRepository i,ICategoryRepository cat){_cardRepository=c;_purchaseRepository=p;_installmentRepository=i;_categoryRepository=cat;}private static bool Valid(string n,decimal l,int c,int d)=>!string.IsNullOrWhiteSpace(n)&&l>=0&&c is>=1 and<=28&&d is>=1 and<=28;public async Task<CreditCard?>CreateCardAsync(string n,decimal l,int c,int d){if(!Valid(n,l,c,d))return null;var x=new CreditCard{Name=n.Trim(),Limit=l,ClosingDay=c,DueDay=d};await _cardRepository.AddAsync(x);await _cardRepository.SaveChangesAsync();return x;}public async Task<CreditCard?>UpdateCardAsync(Guid id,string n,decimal l,int c,int d){var x=await _cardRepository.GetByIdAsync(id);if(x is null||!Valid(n,l,c,d))return null;x.Name=n.Trim();x.Limit=l;x.ClosingDay=c;x.DueDay=d;_cardRepository.Update(x);await _cardRepository.SaveChangesAsync();return x;}public async Task<bool>DeleteCardAsync(Guid id){var x=await _cardRepository.GetByIdAsync(id);if(x is null)return false;x.IsActive=false;_cardRepository.Update(x);await _cardRepository.SaveChangesAsync();return true;}public Task<List<CreditCard>>GetCardsAsync()=>_cardRepository.GetAllAsync();public async Task<CreditCardPurchase?>CreatePurchaseAsync(Guid cardId,Guid? catId,string desc,decimal total,int count,DateTime date){if(!await PurchaseValid(cardId,catId,desc,total,count))return null;var card=(await _cardRepository.GetByIdAsync(cardId))!;date=Utc(date);var p=new CreditCardPurchase{CreditCardId=cardId,CategoryId=catId,Description=desc.Trim(),TotalAmount=total,InstallmentsCount=count,PurchaseDate=date};await _purchaseRepository.AddAsync(p);await AddInstallments(p,card);await _purchaseRepository.SaveChangesAsync();return p;}public async Task<CreditCardPurchase?>UpdatePurchaseAsync(Guid id,Guid cardId,Guid? catId,string desc,decimal total,int count,DateTime date){var p=await _purchaseRepository.GetByIdAsync(id);if(p is null||!await PurchaseValid(cardId,catId,desc,total,count))return null;var all=await _installmentRepository.GetAllAsync();var old=all.Where(x=>x.CreditCardPurchaseId==id).ToList();if(old.Any(x=>x.IsPaid))return null;foreach(var i in old)_installmentRepository.Remove(i);p.CreditCardId=cardId;p.CategoryId=catId;p.Description=desc.Trim();p.TotalAmount=total;p.InstallmentsCount=count;p.PurchaseDate=Utc(date);_purchaseRepository.Update(p);await AddInstallments(p,(await _cardRepository.GetByIdAsync(cardId))!);await _purchaseRepository.SaveChangesAsync();return p;}public async Task<bool>DeletePurchaseAsync(Guid id){var p=await _purchaseRepository.GetByIdAsync(id);if(p is null)return false;var all=await _installmentRepository.GetAllAsync();var items=all.Where(x=>x.CreditCardPurchaseId==id).ToList();if(items.Any(x=>x.IsPaid))return false;foreach(var i in items)_installmentRepository.Remove(i);_purchaseRepository.Remove(p);await _purchaseRepository.SaveChangesAsync();return true;}public async Task<CreditCardInvoiceSummary?>GetInvoiceAsync(Guid id,int y,int m){var card=await _cardRepository.GetByIdAsync(id);if(card is null||m is<1 or>12)return null;var items=await _installmentRepository.GetByCardAndReferenceAsync(id,y,m);var reference=new DateTime(y,m,1,0,0,0,DateTimeKind.Utc);return new CreditCardInvoiceSummary{CreditCardId=card.Id,CreditCardName=card.Name,Year=y,Month=m,DueDate=Due(reference,card.ClosingDay,card.DueDay),TotalAmount=items.Sum(x=>x.Amount),PaidAmount=items.Where(x=>x.IsPaid).Sum(x=>x.Amount),Items=items.Select(x=>new CreditCardInvoiceItem{InstallmentId=x.Id,PurchaseId=x.CreditCardPurchaseId,Description=x.CreditCardPurchase?.Description??string.Empty,InstallmentNumber=x.Number,InstallmentsCount=x.CreditCardPurchase?.InstallmentsCount??0,Amount=x.Amount,IsPaid=x.IsPaid,CategoryId=x.CreditCardPurchase?.CategoryId}).ToList()};}public async Task<bool>MarkInstallmentPaidAsync(Guid id){var x=await _installmentRepository.GetByIdAsync(id);if(x is null)return false;x.IsPaid=true;_installmentRepository.Update(x);await _installmentRepository.SaveChangesAsync();return true;}private async Task<bool>PurchaseValid(Guid cardId,Guid? catId,string desc,decimal total,int count){var card=await _cardRepository.GetByIdAsync(cardId);if(card is null||!card.IsActive||string.IsNullOrWhiteSpace(desc)||total<=0||count<1||count>120)return false;if(catId.HasValue){var cat=await _categoryRepository.GetByIdAsync(catId.Value);if(cat is null||cat.Type!=EntryType.Debit)return false;}return true;}private async Task AddInstallments(CreditCardPurchase p,CreditCard card){var baseAmount=Math.Floor((p.TotalAmount/p.InstallmentsCount)*100m)/100m;var first=First(p.PurchaseDate,card.ClosingDay);for(var n=1;n<=p.InstallmentsCount;n++){var reference=first.AddMonths(n-1);await _installmentRepository.AddAsync(new CreditCardInstallment{CreditCardPurchaseId=p.Id,Number=n,Amount=n==p.InstallmentsCount?p.TotalAmount-baseAmount*(p.InstallmentsCount-1):baseAmount,ReferenceDate=reference,DueDate=Due(reference,card.ClosingDay,card.DueDay)});}}private static DateTime Utc(DateTime d)=>DateTime.SpecifyKind(d,DateTimeKind.Utc);private static DateTime First(DateTime d,int close){var m=new DateTime(d.Year,d.Month,1,0,0,0,DateTimeKind.Utc);return d.Day<=close?m:m.AddMonths(1);}private static DateTime Due(DateTime r,int close,int due){var m=due>close?r:r.AddMonths(1);return new DateTime(m.Year,m.Month,due,0,0,0,DateTimeKind.Utc);}}
